INSERT INTO "inquiry" (inquiry_id, member_id, title, content, is_secret, created_at, updated_at) VALUES
                                                                                                     (1, 8, '자기소개서 첨삭 요청', '작성한 자기소개서를 검토받고 싶습니다. 부족한 부분이 있으면 알려주세요.', FALSE, NOW(), NOW()),
                                                                                                     (2, 8, '면접 예상 질문 문의', '지원하는 직무와 관련하여 예상 질문을 받을 수 있나요?', FALSE, NOW(), NOW()),
                                                                                                     (3, 6, '자기소개서 문항 이해 관련', '제시된 자기소개서 문항의 의미를 잘 모르겠습니다. 해석이 필요합니다.', FALSE, NOW(), NOW()),
                                                                                                     (4, 6, '비공개: 면접 답변 조언 요청', '1분 자기소개와 지원 동기 답변을 수정하고 싶습니다. 의견 부탁드립니다.', TRUE, NOW(), NOW()),
                                                                                                     (5, 6, '글자 수 제한 문의', '자기소개서 문항마다 글자 수 제한이 있나요? 플랫폼에서 지원되는 최대 글자 수가 궁금합니다.', FALSE, NOW(), NOW()),
                                                                                                     (6, 9, '비공개: 취업 지원서 작성 조언', '취업 지원서 작성에서 중요한 포인트를 알고 싶습니다.', TRUE, NOW(), NOW()),
                                                                                                     (7, 9, 'AI 분석 서비스 사용법 문의', 'AI를 활용한 자기소개서 분석 서비스의 사용법이 궁금합니다.', FALSE, NOW(), NOW()),
                                                                                                     (8, 7, '첨부 파일 업로드 오류', '첨부 파일을 업로드할 때 에러가 발생합니다. 해결 방법을 알려주세요.', FALSE, NOW(), NOW()),
                                                                                                     (9, 6, '비공개: 면접 예상 질문 맞춤형 제공 요청', '저의 경력을 기반으로 한 맞춤형 면접 예상 질문을 요청합니다.', TRUE, NOW(), NOW()),
                                                                                                     (10, 8, '피드백 반영 후 수정 문의', '피드백 반영 후 수정된 자기소개서를 다시 검토받고 싶습니다. 절차가 어떻게 되나요?', FALSE, NOW(), NOW());
INSERT INTO "inquiry_reply" (inquiry_reply_id, inquiry_id, member_id, content, created_at, updated_at) VALUES
                                                                                                           (1, 1, 3, '작성하신 자기소개서를 확인했습니다. 첫 문장의 강렬함과 지원 동기 부분을 보완하는 것이 좋겠습니다.', NOW(), NOW()), -- 문의 1에 대한 답변
                                                                                                           (2, 2, 1, '지원하는 직무에서 자주 나오는 질문은 “이 직무를 선택한 이유는 무엇인가요?”와 “관련 경험을 설명해보세요”입니다.', NOW(), NOW()), -- 문의 2에 대한 답변
                                                                                                           (3, 3, 2, '제시된 문항의 핵심은 본인의 직무 역량과 관련 경험을 강조하라는 의미입니다. 이 점을 중심으로 작성해보세요.', NOW(), NOW()), -- 문의 3에 대한 답변
                                                                                                           (4, 4, 2, '1분 자기소개는 자신의 강점을 요약적으로 표현하며, 지원 동기는 회사의 가치와 연결 지어 작성하면 좋습니다.', NOW(), NOW()), -- 비공개 문의 4에 대한 답변
                                                                                                           (5, 5, 4, '글자 수 제한은 문항마다 다르며, 플랫폼에서는 최대 2,000자를 지원합니다.', NOW(), NOW()), -- 문의 5에 대한 답변
                                                                                                           (6, 6, 2, '취업 지원서를 작성할 때 가장 중요한 포인트는 직무와 연관된 경험과 성과를 구체적으로 기술하는 것입니다.', NOW(), NOW()), -- 비공개 문의 6에 대한 답변
                                                                                                           (7, 7, 2, 'AI 분석 서비스는 자기소개서를 업로드하면 키워드 분석과 적합성 평가 결과를 제공합니다. 도움말 페이지를 참고하세요.', NOW(), NOW()), -- 문의 7에 대한 답변
                                                                                                           (8, 8, 4, '첨부 파일 업로드 오류는 파일 크기 제한(10MB) 또는 지원하지 않는 형식 때문일 수 있습니다. 파일 형식을 확인해 주세요.', NOW(), NOW()), -- 문의 8에 대한 답변
                                                                                                           (9, 9, 1, '경력을 기반으로 한 맞춤형 면접 예상 질문은 AI 분석 서비스에서 제공됩니다. 서비스 이용을 추천드립니다.', NOW(), NOW()), -- 비공개 문의 9에 대한 답변
                                                                                                           (10, 10, 2, '수정된 자기소개서를 다시 검토받으려면 동일 문항으로 재요청하시면 됩니다.', NOW(), NOW()); -- 문의 10에 대한 답변
